CREATE TABLE IF NOT EXISTS equipment (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(30) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL, category VARCHAR(60), status VARCHAR(20) NOT NULL, condition_state VARCHAR(20) NOT NULL, location VARCHAR(80));
CREATE TABLE IF NOT EXISTS activity (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, equipment_id BIGINT, action VARCHAR(30), person VARCHAR(80), note VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO equipment(code,name,category,status,condition_state,location) SELECT 'MIC-001','Compound Microscope','Optics','AVAILABLE','GOOD','Cabinet A' WHERE NOT EXISTS(SELECT 1 FROM equipment);
